package location

import (
	"encoding/json"
	"testing"
)

func TestLocationJSON(t *testing.T) {
	in := Location{ID: 123, Name: "Rachel's Floral Designs", Coordinates: "115,277"}
	data, err := json.Marshal(in)
	if err != nil {
		t.Fatal(err)
	}
	const want = `{"locID":"123","id":"Rachel's Floral Designs","coordinates":"115,277"}`
	if string(data) != want {
		t.Errorf("got %s, want %s", data, want)
	}
	var out Location
	if err := json.Unmarshal(data, &out); err != nil {
		t.Fatal(err)
	}
	if out != in {
		t.Errorf("round trip: got %+v, want %+v", out, in)
	}
}
EOF
